from __future__ import annotations

from html import escape
from urllib.parse import quote

from fastapi import APIRouter, Request
from fastapi.responses import HTMLResponse, RedirectResponse

from .branding import PRODUCT_FULL_NAME
from .tenant_storage import project_path

router = APIRouter()


@router.get("/voice-house/{project_name}", response_class=HTMLResponse, include_in_schema=False)
def voice_house(project_name: str, request: Request):
    member = getattr(request.state, "member", None)
    if member is None:
        return RedirectResponse(f"/signin?next=/voice-house/{quote(project_name, safe='')}", status_code=303)
    try:
        project_path(project_name, must_exist=True)
    except Exception:
        return HTMLResponse("<h1>Project not found</h1>", status_code=404)
    encoded = quote(project_name, safe="")
    brand = escape(PRODUCT_FULL_NAME)
    html = r"""<!doctype html><html lang='en'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><meta name='robots' content='noindex,nofollow'><title>Voice House — __BRAND__</title><style>
:root{--bg:#03040a;--panel:#0e1120;--line:#ffffff20;--gold:#e9c86f;--violet:#9d72ff;--pink:#ec6dcc;--green:#76e1aa;--red:#ff8da4;--muted:#bbc1d2;--text:#fff}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 8% 0,#4c1a745e,transparent 28%),radial-gradient(circle at 94% 1%,#6b184d45,transparent 24%),#03040a;color:#fff;font-family:Inter,ui-sans-serif,system-ui,sans-serif;min-height:100vh}a{color:inherit;text-decoration:none}.wrap{width:min(1450px,calc(100% - 28px));margin:auto}.nav{position:sticky;top:0;z-index:10;background:#05060bef;border-bottom:1px solid var(--line);backdrop-filter:blur(18px)}.navin{min-height:70px;display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}.brand{font-weight:950}.brand small{display:block;color:var(--gold);font-size:.65rem;text-transform:uppercase;letter-spacing:.09em}.btn,button{border:1px solid var(--line);border-radius:11px;padding:9px 12px;background:#ffffff08;color:#fff;font:inherit;font-weight:850;cursor:pointer}.primary{border:0!important;background:linear-gradient(115deg,var(--gold),var(--violet),var(--pink))!important;color:#160d1c!important}.danger{border-color:#ff8da455!important;color:#ffd8df!important}.good{border-color:#76e1aa55!important;color:var(--green)!important}.hero{padding:38px 0 18px}.eyebrow{font-size:.7rem;letter-spacing:.16em;text-transform:uppercase;color:var(--gold);font-weight:950}h1{font-size:clamp(2.5rem,6vw,5rem);line-height:.94;letter-spacing:-.05em;margin:.14em 0 .2em}.lead,.muted{color:var(--muted);line-height:1.6}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px;padding-bottom:55px}.card{border:1px solid var(--line);border-radius:19px;background:linear-gradient(145deg,#111628ed,#090c18f2);padding:16px;margin:10px 0}.form{display:grid;gap:9px}.row{display:grid;grid-template-columns:1fr 1fr;gap:9px}.field,input,textarea,select{width:100%;border:1px solid var(--line);border-radius:11px;padding:10px;background:#060912;color:#fff;font:inherit;outline:none}textarea{min-height:90px;resize:vertical}.check{border:1px solid var(--line);border-radius:11px;padding:9px;background:#ffffff04}.check input{width:auto}.profile{border:1px solid var(--line);border-radius:14px;padding:12px;margin:8px 0;background:#ffffff05}.pill{display:inline-block;border:1px solid var(--line);border-radius:999px;padding:4px 8px;font-size:.7rem;margin:2px}.pill.good{color:var(--green)}.pill.bad{color:#ffd8df;border-color:#ff8da455}.challenge{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:1.02rem;background:#ffffff08;padding:13px;border-radius:12px;border:1px solid var(--gold);user-select:all}.notice{display:none;border:1px solid var(--line);border-radius:12px;padding:11px;margin:10px 0}.notice.show{display:block}.notice.bad{border-color:#ff8da455;color:#ffd8df}.empty{padding:22px;text-align:center;color:var(--muted);border:1px dashed #ffffff2d;border-radius:14px}.result{border-left:4px solid var(--green);padding:12px;background:#76e1aa08;border-radius:12px;overflow-wrap:anywhere}@media(max-width:900px){.grid{grid-template-columns:1fr}}@media(max-width:600px){.row{grid-template-columns:1fr}}
</style></head><body><nav class='nav'><div class='wrap navin'><a class='brand' href='/song-editor/__PROJECT__'>__BRAND__<small>Voice House · consent-controlled vocal identity</small></a><div><a class='btn' href='/song-editor/__PROJECT__'>Song DNA</a> <a class='btn' href='/daw'>DAW</a> <a class='btn' href='/dashboard'>Dashboard</a></div></div></nav><main class='wrap'><section class='hero'><div class='eyebrow'>Your voice stays permissioned</div><h1>Clone, convert and harmonise — with consent attached.</h1><p class='lead'>Voice Profiles are project-scoped identity records. Aura stores consent evidence and approved uses, hides raw reference paths from the browser, applies similarity limits, and disables every downstream use immediately when a profile is revoked.</p><div id='notice' class='notice'></div></section><section class='grid'><div><div class='card'><div class='eyebrow'>1 · Identity verification</div><h2>Create a Voice Profile</h2><p class='muted'>Generate a one-time phrase, record yourself saying it clearly, and upload one or more clean reference samples. If local STT is configured, Aura checks the spoken phrase. Otherwise the profile remains explicitly <b>attested</b>, not falsely “verified.”</p><button class='primary' onclick='challenge()'>Generate verification phrase</button><div id='challengeBox'></div><form id='profileForm' class='form' style='margin-top:12px'><input type='hidden' name='challenge_id' id='challengeId'><div class='row'><div><label>Profile name</label><input name='name' required placeholder='My singing voice'></div><div><label>Voice owner</label><input name='owner_label' required placeholder='Name / authorised performer'></div></div><label>Consent statement</label><textarea name='consent_statement' required placeholder='I confirm this is my voice (or I am authorised by the voice owner) and permit the selected uses in this project.'></textarea><div class='row'><label class='check'><input type='checkbox' name='singing' checked> Singing generation</label><label class='check'><input type='checkbox' name='backing_harmony' checked> Backing harmonies</label></div><div class='row'><label class='check'><input type='checkbox' name='voice_conversion' checked> Voice conversion</label><label class='check'><input type='checkbox' name='dubbing'> Dubbing / speech</label></div><label>Similarity ceiling</label><input name='similarity_limit' type='number' min='0' max='1' step='.05' value='.8'><label>Verification recording — read the generated phrase</label><input name='verification_recording' type='file' accept='audio/*' required><label>Voice reference samples</label><input name='reference_files' type='file' accept='audio/*' multiple required><label class='check'><input name='consent_confirmed' type='checkbox' value='true' required> I confirm the voice owner has authorised these selected uses and can revoke this profile.</label><button class='primary' type='submit'>Create consent-controlled Voice Profile</button></form><div id='createResult'></div></div><div class='card'><div class='eyebrow'>Your Voice Profiles</div><div id='profiles'><div class='empty'>Loading…</div></div></div></div><div><div class='card'><div class='eyebrow'>2 · Performance-preserving conversion</div><h2>Change timbre, keep the performance.</h2><p class='muted'>Seed-VC/RVC-compatible conversion preserves the source vocal's timing and expression while applying an authorised Voice Profile. The configured local conversion engine must be available.</p><form id='convertForm' class='form'><label>Source vocal/audio asset</label><select id='convertAsset' required></select><label>Voice Profile</label><select id='convertProfile' required></select><div class='row'><div><label>Similarity</label><input name='similarity' type='number' min='0' max='1' step='.05' value='.8'></div><div><label>Pitch shift semitones</label><input name='pitch_shift' type='number' min='-24' max='24' step='1' value='0'></div></div><button class='primary'>Convert singing voice</button></form><div id='convertResult'></div></div><div class='card'><div class='eyebrow'>3 · Harmony & choir</div><h2>Generate backing voices around the lead.</h2><form id='harmonyForm' class='form'><label>Lead vocal/audio asset</label><select id='harmonyAsset' required></select><div class='row'><div><label>Mode</label><select name='mode'><option value='contextual'>Contextual neural harmony</option><option value='scored'>Scored harmony/MIDI control</option></select></div><div><label>Key</label><input name='key' value='C Major'></div></div><label>Optional Voice Profile for scored harmonies</label><select id='harmonyProfile'><option value=''>No cloned profile</option></select><textarea name='prompt'>Natural supportive backing harmonies, blended behind the lead vocal.</textarea><button class='primary'>Generate harmonies</button></form><div id='harmonyResult'></div></div><div class='card'><div class='eyebrow'>Voice safety contract</div><p class='muted'>Revocation is immediate. A revoked profile cannot be used for conversion, singing or harmonies. Attested profiles are conservatively capped; local phrase verification can support a higher verified state. Reference paths remain server-side.</p></div></div></section></main><script>
const PROJECT='__PROJECT__',$=id=>document.getElementById(id);let profiles=[],assets=[];function esc(v){return String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}function notice(m,b=false){const n=$('notice');n.textContent=m;n.className='notice show'+(b?' bad':'');clearTimeout(window._n);window._n=setTimeout(()=>n.className='notice',7500)}async function req(url,opt={}){const r=await fetch(url,{credentials:'same-origin',headers:{'Content-Type':'application/json',...(opt.headers||{})},...opt});let b={};try{b=await r.json()}catch(e){}if(!r.ok)throw new Error(b.detail||`Request failed (${r.status})`);return b}
async function challenge(){try{const d=await req(`/projects/${PROJECT}/voice-house/challenge`,{method:'POST'});$('challengeId').value=d.challenge_id;$('challengeBox').innerHTML=`<p class="muted">Read this exact phrase:</p><div class="challenge">${esc(d.phrase)}</div><p class="muted">Expires ${esc(d.expires_at)}</p>`;notice('Verification phrase created. Record it before the challenge expires.')}catch(e){notice(e.message,true)}}
$('profileForm').addEventListener('submit',async e=>{e.preventDefault();if(!$('challengeId').value)return notice('Generate a verification phrase first.',true);const fd=new FormData(e.target);const uses=['singing','backing_harmony','voice_conversion','dubbing'].filter(x=>fd.get(x)==='on');fd.set('allowed_uses',uses.join(','));fd.delete('singing');fd.delete('backing_harmony');fd.delete('voice_conversion');fd.delete('dubbing');$('createResult').innerHTML='<p class="muted">Analysing voice references and consent evidence…</p>';try{const r=await fetch(`/projects/${PROJECT}/voice-house/profiles`,{method:'POST',credentials:'same-origin',body:fd});let b={};try{b=await r.json()}catch(_){}if(!r.ok)throw new Error(b.detail||`Request failed (${r.status})`);const p=b.voice_profile;$('createResult').innerHTML=`<div class="result"><b>${esc(p.name)}</b> · ${esc(p.verification_state)} · similarity ceiling ${esc(p.similarity_limit)}</div>`;e.target.reset();$('challengeId').value='';$('challengeBox').innerHTML='';await load();notice('Voice Profile created with its consent state recorded.')}catch(err){$('createResult').innerHTML='';notice(err.message,true)}})
async function load(){try{const [p,a]=await Promise.all([req(`/projects/${PROJECT}/voice-house/profiles`),req(`/projects/${PROJECT}/voice-house/audio-assets`)]);profiles=p.profiles||[];assets=a.assets||[];renderProfiles();fillSelects()}catch(e){notice(e.message,true)}}function renderProfiles(){$('profiles').innerHTML=profiles.length?profiles.map(p=>`<div class="profile"><div><b>${esc(p.name)}</b><span class="pill ${p.active?'good':'bad'}">${esc(p.verification_state)}</span></div><div class="muted">Owner: ${esc(p.owner_label)} · similarity ≤ ${esc(p.similarity_limit)} · ${esc((p.allowed_uses||[]).join(', '))}</div>${p.active?`<button class="danger" onclick="revoke('${p.id}')">Revoke profile</button>`:`<p class="muted">Revoked ${esc(p.revoked_at||'')}</p>`}</div>`).join(''):'<div class="empty">No Voice Profiles yet.</div>'}function options(items,value,label){return items.map(x=>`<option value="${esc(x[value])}">${esc(x[label])}</option>`).join('')}function fillSelects(){const ao=options(assets,'id','name')||'<option value="">No audio assets</option>',active=profiles.filter(x=>x.active),po=options(active,'id','name')||'<option value="">No active Voice Profiles</option>';$('convertAsset').innerHTML=ao;$('harmonyAsset').innerHTML=ao;$('convertProfile').innerHTML=po;$('harmonyProfile').innerHTML='<option value="">No cloned profile</option>'+options(active,'id','name')}
async function revoke(id){if(!confirm('Revoke this Voice Profile? Downstream use will be blocked immediately.'))return;const reason=prompt('Reason for revocation','Consent withdrawn')||'Consent withdrawn';try{await req(`/projects/${PROJECT}/voice-house/profiles/${id}/revoke`,{method:'POST',body:JSON.stringify({reason})});await load();notice('Voice Profile revoked and disabled.')}catch(e){notice(e.message,true)}}
$('convertForm').addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(e.target);try{const d=await req(`/projects/${PROJECT}/voice-convert`,{method:'POST',body:JSON.stringify({source_asset_id:$('convertAsset').value,voice_profile_id:$('convertProfile').value,similarity:Number(fd.get('similarity')||.8),pitch_shift:Number(fd.get('pitch_shift')||0)})});$('convertResult').innerHTML=`<div class="result"><b>Converted vocal created.</b><div class="muted">${esc(d.path)}</div></div>`;notice('Consent-checked voice conversion completed.')}catch(err){notice(err.message,true)}})
$('harmonyForm').addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(e.target);try{const d=await req(`/projects/${PROJECT}/harmonies`,{method:'POST',body:JSON.stringify({source_asset_id:$('harmonyAsset').value,mode:fd.get('mode'),key:fd.get('key'),voices:['third_above','third_below'],voice_profile_id:$('harmonyProfile').value||null,prompt:fd.get('prompt')||''})});$('harmonyResult').innerHTML=`<div class="result"><b>Harmony generation completed.</b><div class="muted">${esc(JSON.stringify(d.stems||{}))}</div></div>`;notice('Backing harmony generated.')}catch(err){notice(err.message,true)}});load();
</script></body></html>"""
    return HTMLResponse(html.replace("__PROJECT__", encoded).replace("__BRAND__", brand))
